const o = phi.observe({ maxElements: 200 });
const inputs = o.nodes.filter(n => /textbox|searchbox|combobox/i.test(n.role));
return { url: o.url, title: o.title, inputs: inputs.map(n => `${n.ref}. ${n.role} "${n.name}"`) };

phi.narrate("Trying the site's own search page for the depot report");
