const q = phi.query("a", { fields: ["href"], limit: 80 });
const hits = q.items.filter(i => i.href && /jamaica|depot|environment/i.test(i.href));
return { url: r.url, title: r.title, total: q.total, hits: hits.slice(0, 30) };

phi.narrate("Typing the depot name into the site search box");
