  const hs = [...document.querySelectorAll("h2,h3,h4")];
  const h = hs.find(x => /^Documents/i.test(x.textContent.trim()));
  if (!h) return { err: "no heading" };
  let node = h;
  const out = [];
  // walk following siblings/containers collecting links
  const container = h.parentElement;
