  return { anchorHref: el ? el.href : null, anchorHTML: el ? el.outerHTML : null, sectionText, docTitles: [...new Set(docs)], pdfInfo };
});
const env = phi.js(() => ({ title: document.title, h1: (document.querySelector("h1")||{}).innerText }));
