const info = phi.goto("https://new.mta.info/project/jamaica-bus-depot-expansion");
const probe = phi.js(async () => {
  const out = {};
  const res = await fetch("/document/10341", { credentials: "include" });
  const buf = await res.arrayBuffer();
  const u8 = new Uint8Array(buf);
  out.status = res.status;
  out.ct = res.headers.get("content-type");
  out.len = u8.length;
  out.magic = String.fromCharCode.apply(null, Array.from(u8.slice(0, 8)));
  const latin = new TextDecoder("latin1").decode(u8);
  out.pageObjs = (latin.match(/\/Type\s*\/Page[^s]/g) || []).length;
  out.encrypted = /\/Encrypt/.test(latin);
  const chunks = [];
  let idx = 0, n = 0;
  const pat = /stream\r?\n/g;
  let m;
  while ((m = pat.exec(latin)) && n < 40) {
    const start = m.index + m[0].length;
    const end = latin.indexOf("endstream", start);
    if (end < 0) break;
    const slice = u8.subarray(start, end);
    n++;
    try {
      const ds = new DecompressionStream("deflate");
      const w = ds.writable.getWriter();
      w.write(slice); w.close();
      const ab = await new Response(ds.readable).arrayBuffer();
      const s = new TextDecoder("latin1").decode(new Uint8Array(ab));
      if (/\bTj\b|\bTJ\b/.test(s)) {
        const parts = [];
        const re = /\((?:\\.|[^\\()])*\)/g;
        let p;
        while ((p = re.exec(s))) parts.push(p[0].slice(1, -1));
        if (parts.length) chunks.push(parts.join(" "));
      }
    } catch (e) { /* skip */ }
    if (chunks.join(" ").length > 4000) break;
  }
  out.streamsTried = n;
  out.chunksFound = chunks.length;
  out.text = chunks.join("\n").slice(0, 3000);
  return out;
});
return { page: info.url, probe };
